// Illustrative only — NOT O(1) on all ops.
// HashSet: O(1) insert/remove/contains, but getRandom is O(n):
//   convert to array each call -> O(n)
// ArrayList: O(1) getRandom/append, but remove(val) is O(n):
//   indexOf is O(n) and removing a middle element shifts the rest O(n)
class NaiveSet {
    private Set<Integer> set = new HashSet<>();
    public boolean insert(int val) { return set.add(val); }
    public boolean remove(int val) { return set.remove(val); }
    public int getRandom() {
        int target = new java.util.Random().nextInt(set.size());
        int i = 0;
        for (int x : set) { if (i++ == target) return x; } // O(n)
        return -1;
    }
}

